		depth,
		expansionRatio: volume / FORMER_BASE_VOLUME,
		foundationStyle: safeVariant % 2 ? 'stepped-stone' : 'retaining-plinth',
		gardenType: ['herbs', 'flowers', 'orchard-edge'][safeVariant % 3],
		minimumExpansion: 1,
